package com.bananalab.lite;
import java.util.*;import java.util.regex.*;
/** Source editing only. No execution of arbitrary project code. */
final class JavaSourceEdit{
 static void filename(String name){if(!name.matches("[A-Z][A-Za-z0-9_]{0,70}\\.java"))throw new IllegalArgumentException("Usá un nombre Java simple, sin rutas.");}
 static int close(String text,int open,char left,char right){int depth=1;char quote=0;boolean escape=false,line=false,block=false;for(int i=open+1;i<text.length();i++){char ch=text.charAt(i),next=i+1<text.length()?text.charAt(i+1):0;if(line){if(ch=='\n')line=false;continue;}if(block){if(ch=='*'&&next=='/'){block=false;i++;}continue;}if(quote!=0){if(escape)escape=false;else if(ch=='\\')escape=true;else if(ch==quote)quote=0;continue;}if(ch=='/'&&next=='/'){line=true;i++;continue;}if(ch=='/'&&next=='*'){block=true;i++;continue;}if(ch=='\"'||ch=='\''){quote=ch;continue;}if(ch==left)depth++;if(ch==right&&--depth==0)return i;}throw new IllegalArgumentException("No encontré el cierre del bloque seleccionado.");}
 static int[] method(String source,String name){if(!name.matches("[A-Za-z_$][A-Za-z0-9_$]{0,70}"))throw new IllegalArgumentException("Método inválido.");Pattern p=Pattern.compile("(?:^|[;{}])\\s*(?:(?:public|private|protected|static|final|synchronized|native|strictfp)\\s+)*(?:[A-Za-z_$][A-Za-z0-9_$<>\\[\\].?,]*)\\s+"+Pattern.quote(name)+"\\s*\\([^;{}]*\\)\\s*(?:throws\\s+[A-Za-z0-9_.,\\s]+)?\\{");Matcher m=p.matcher(SourceLex.masked(source));int[] found=null;while(m.find()){if(found!=null)throw new IllegalArgumentException("Hay sobrecargas; elegí un método único o editá el archivo completo.");int open=m.end()-1;found=new int[]{open+1,close(source,open,'{','}')};}if(found==null)throw new IllegalArgumentException("No encontré una declaración no ambigua de "+name+".");return found;}
 static String replace(String source,String name,String body){if(body.length()>8000||body.trim().isEmpty())throw new IllegalArgumentException("Cuerpo vacío o demasiado largo (máximo8000).");int[] span=method(source,name);return source.substring(0,span[0])+"\n"+body.trim()+"\n"+source.substring(span[1]);}
 static String arithmetic(String source,String method,String operation){int[] span=method(source,method);String body=source.substring(span[0],span[1]).trim();if(!body.startsWith("return ")||!body.endsWith(";")||body.indexOf(';')!=body.length()-1)throw new IllegalArgumentException("El especialista necesita un método con un único return aritmético.");String expression=body.substring(7,body.length()-1).trim();int depth=0,position=-1;for(int i=0;i<expression.length();i++){char c=expression.charAt(i);if(c=='(')depth++;else if(c==')')depth--;else if(depth==0&&"+-*/".indexOf(c)>=0){if(position>=0||i==0)throw new IllegalArgumentException("Expresión ambigua; editá el método manualmente.");position=i;}else if(c=='\"'||c=='\''||c=='?'||c==';'||c=='{')throw new IllegalArgumentException("Fuera del especialista aritmético.");}if(position<0)throw new IllegalArgumentException("No encontré un operador binario de nivel superior.");String left=expression.substring(0,position).trim(),right=expression.substring(position+1).trim();if(left.isEmpty()||right.isEmpty())throw new IllegalArgumentException("Falta un operando.");String next;if(operation.equals("min")||operation.equals("max"))next="Math."+operation+"("+left+", "+right+")";else{if(!operation.matches("[+*/-]"))throw new IllegalArgumentException("Operación no admitida.");next="("+left+") "+operation+" ("+right+")";}return replace(source,method,"return "+next+";");}
}
